import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveEntry_equals_TriageGen0Test {

    @Test
    public void testEquals_SameInstance() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        assertTrue(entry.equals(entry));
    }

    @Test
    public void testEquals_NullObject() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        assertFalse(entry.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        String differentClass = "test.txt";
        assertFalse(entry.equals(differentClass));
    }

    @Test
    public void testEquals_NullName_OtherNameNotNull() {
        // To test the branch where myName is null and otherName is not null
        // We need a way to create a ZipArchiveEntry with a null name.
        // Since the constructor sets the name, we use reflection or a subclass if necessary,
        // but based on the provided code, we'll assume the constructor allows it or we simulate via internal state.
        // Given the provided code logic: if (myName == null) { if (otherName != null) return false; }

        ZipArchiveEntry entry1 = new ZipArchiveEntry(null);
        ZipArchiveEntry entry2 = new ZipArchiveEntry("something");

        assertFalse(entry1.equals(entry2));
    }

    @Test
    public void testEquals_NullName_OtherNameNull() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry(null);
        ZipArchiveEntry entry2 = new ZipArchiveEntry(null);

        // Looking at the code:
        // if (myName == null) { if (otherName != null) return false; } 
        // If both are null, it falls through to 'return true;'
        assertTrue(entry1.equals(entry2));
    }

    @Test
    public void testEquals_NameNotNull_TriggerFalseBranch() {
        // The code contains a suspicious branch:
        // else if (!false) { return false; }
        // Since !false is always true, if myName is NOT null, it will always return false.
        // This is likely a bug in the provided source code, but to maximize coverage, we must trigger it.

        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");

        // Based on the logic: myName is "test.txt" (not null). 
        // It enters the 'else if (!false)' block and returns false.
        assertFalse(entry1.equals(entry2));
    }

    @Test
    public void testEquals_DifferentNames() {
        // This tests the path where names are not null, which triggers the !false branch.
        ZipArchiveEntry entry1 = new ZipArchiveEntry("a");
        ZipArchiveEntry entry2 = new ZipArchiveEntry("b");

        assertFalse(entry1.equals(entry2));
    }
}
